fn mk_filled_vec(n: usize, val: f32) -> Vec<f32> {
    vec![val; n]
}

fn lagval3d(x: Vec<f32>, y: Vec<f32>, z: Vec<f32>, c: Vec<Vec<Vec<f32>>>) -> Vec<f32> {
    // Check that the input arrays have equal length and are positive
    let len = x.len();
    assert!(len > 0, "Input arrays must have positive length.");
    assert!(len == y.len(), "Input arrays must have equal length.");
    assert!(len == z.len(), "Input arrays must have equal length.");

    // Check the dimensions of the coefficient tensor
    let c_len_0 = c.len();
    assert!(c_len_0 > 0, "Coefficient tensor must be non-empty in the first dimension.");
    let c_len_1 = c[0].len();
    assert!(c_len_1 > 0, "Coefficient tensor must be non-empty in the second dimension.");
    let c_len_2 = c[0][0].len();
    assert!(c_len_2 > 0, "Coefficient tensor must be non-empty in the third dimension.");

    // Special case: if the coefficient tensor has shape 1x1x1
    if c_len_0 == 1 && c_len_1 == 1 && c_len_2 == 1 {
        let coefficient = c[0][0][0];
        return mk_filled_vec(len, coefficient);
    }

    // In all other cases, return a vector of zeros
    mk_filled_vec(len, 0.0)
}

fn main() {
    // Example usage
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0, 6.0];
    let z = vec![7.0, 8.0, 9.0];
    let c = vec![vec![vec![10.0]]]; // 1x1x1 tensor

    let result = lagval3d(x, y, z, c);
    println!("{:?}", result); // Should print: [10.0, 10.0, 10.0]

    let c2 = vec![vec![vec![10.0]], vec![vec![20.0]]]; // 2x1x1 tensor
    let result2 = lagval3d(x, y, z, c2);
    println!("{:?}", result2); // Should print: [0.0, 0.0, 0.0]
}